import java.io.*;
import java.util.*;

abstract class Vehicle {
    abstract double fuelEfficiency();
}

class Car extends Vehicle {
    private double distance;
    private double fuel;

    public Car(double distance, double fuel) {
        this.distance = distance;
        this.fuel = fuel;
    }

    @Override
    double fuelEfficiency() {
        if (fuel == 0) {
            return 0.0;
        }
        return distance / fuel;
    }
}

class Truck extends Vehicle {
    private double distance;
    private double fuel;

    public Truck(double distance, double fuel) {
        this.distance = distance;
        this.fuel = fuel;
    }

    @Override
    double fuelEfficiency() {
        if (fuel == 0) {
            return 0.0;
        }
        return distance / fuel;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNext()) {
            sc.close();
            return;
        }

        String vehicleType = sc.next();
        double distance = sc.nextDouble();
        double fuel = sc.nextDouble();

        Vehicle v;
        if (vehicleType.equalsIgnoreCase("Car")) {
            v = new Car(distance, fuel);
        } else {
            v = new Truck(distance, fuel);
        }

        System.out.println("Fuel Efficiency: " + v.fuelEfficiency());

        sc.close();
    }
}
